/**
 * Parse an LRC document, plain or enhanced, into lines with optional word level parts.
 *
 * The result is returned exactly as the document states it. `LRCParser.parse` runs `lrcFixers` over
 * it afterwards, which is right for Musixmatch word-by-word lyrics and wrong for sources whose
 * timings are already clean, so callers that know their source can stay on this function.
 */
export declare function parseLRC(lrcText: string, songDurationMs: number): Lyric[];

/**
 * Parse a QRC document, either the `<QrcInfos>` envelope QQ Music returns or a bare QRC body.
 *
 * `metadata` is optional and only used to drop opening lines that echo the song title or artist,
 * which QQ Music routinely prepends to a lyric body.
 */
export declare function parseQRC(qrcXml: string, songDurationMs: number, metadata?: QrcMetadata): Lyric[];

export declare function parseTTMLContent(xml: string, options?: ParseTTMLOptions): ParsedTTML;

declare interface ParseTTMLOptions {
    /** Silence longer than this becomes an instrumental line. Defaults to 5000. */
    instrumentalGapMs?: number;
    /** Used for the outro instrumental when the document's `<body>` carries no `dur`. */
    songDurationMs?: number;
}

/**
 * Parse time in hh:mm:ss.xx or offset-time with unit indicators "h", "m", "s", "ms" (e.g 432.25s)
 */
export declare function parseTTMLTime(timeStr: string | number | undefined): number;

